VALUES ('guan-yu', '关羽', 'shu', ARRAY[]::text[], NULL, NULL, 160, 1, NULL, 'year', 220, 1, NULL, 'year', ARRAY['将领'], '蜀汉名将，襄樊之战北伐曹魏，兵败被俘遇害；关羽被杀后孙权送其首级给曹操；蜀汉追谥壮缪侯，民间崇奉逐渐神化。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/关羽"}]'::jsonb, NULL, NULL, NULL)
