VALUES ('cao-xiu', '曹休', 'wei', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, 228, 6, NULL, 'month', ARRAY['将领'], '曹魏宗室将领，字文烈，沛国谯人，曹操族子。随军征讨孙权、蜀汉，历任征东将军等职；石亭之战被吴将陆逊击败，后因病去世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹休"}]'::jsonb, NULL, NULL, NULL)
